(()=>{
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function rectangle(w,h,zoom,x,y){const size=Math.min(w,h)/clamp(zoom,1,4);return {x:(w-size)*clamp(x,0,100)/100,y:(h-size)*clamp(y,0,100)/100,size}}
let dismiss=null,selection=0;function cancelPending(){selection++;dismiss?.()}window.addEventListener?.('hashchange',cancelPending);window.addEventListener?.('pagehide',cancelPending);
async function open(file){cancelPending();const selected=selection;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Выбери JPG, PNG или WebP размером до 5 МБ.');
let image,url;try{if(typeof createImageBitmap==='function')image=await createImageBitmap(file);else{url=URL.createObjectURL(file);image=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('Не удалось открыть фото.'));i.src=url})}if(selected!==selection)return null;const w=image.width||image.naturalWidth,h=image.height||image.naturalHeight;if(!w||!h||w*h>16000000)throw Error('Фото слишком большое по разрешению. Выбери уменьшенную копию.');
return await new Promise((resolve,reject)=>{const dialog=document.createElement('dialog');dialog.className='avatar-crop-dialog';dialog.setAttribute('aria-labelledby','crop-heading');dialog.innerHTML='<h2 id="crop-heading">Выбери кадр для аватара</h2><p>Перемести фото, чтобы лицо целиком попало в круг.</p><canvas class="avatar-crop-preview" width="512" height="512" aria-label="Предпросмотр аватара. Фото можно перемещать мышью или пальцем."></canvas><label>Масштаб<input data-crop="zoom" type="range" min="1" max="4" step="0.01" value="1"></label><details><summary>Точное положение</summary><label>Влево — вправо<input data-crop="x" type="range" min="0" max="100" step="1" value="50"></label><label>Вверх — вниз<input data-crop="y" type="range" min="0" max="100" step="1" value="0"></label></details><p class="avatar-crop-status" role="status"></p><div class="avatar-crop-actions"><button type="button" class="btn alt" data-crop="cancel">Отмена</button><button type="button" class="btn" data-crop="save">Сохранить аватар</button></div>';
const canvas=dialog.querySelector('canvas'),ctx=canvas.getContext('2d'),zoom=dialog.querySelector('[data-crop=zoom]'),x=dialog.querySelector('[data-crop=x]'),y=dialog.querySelector('[data-crop=y]'),save=dialog.querySelector('[data-crop=save]'),status=dialog.querySelector('[role=status]'),previous=document.activeElement;let closed=false,drag=null;
function finish(value,error){if(closed)return;closed=true;window.removeEventListener('hashchange',cancel);window.removeEventListener('pagehide',cancel);dismiss=null;try{dialog.close()}catch{}dialog.remove();previous?.focus?.();error?reject(error):resolve(value)}
function cancel(){finish(null)}dismiss=cancel;
function render(){const r=rectangle(w,h,Number(zoom.value),Number(x.value),Number(y.value));ctx.clearRect(0,0,512,512);ctx.drawImage(image,r.x,r.y,r.size,r.size,0,0,512,512);ctx.fillStyle='rgba(0,0,0,.5)';ctx.beginPath();ctx.rect(0,0,512,512);ctx.arc(256,256,254,0,Math.PI*2,true);ctx.fill('evenodd');ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(256,256,253,0,Math.PI*2);ctx.stroke()}
for(const slider of [zoom,x,y])slider.addEventListener('input',render);
canvas.onpointerdown=e=>{const r=rectangle(w,h,Number(zoom.value),Number(x.value),Number(y.value));drag={id:e.pointerId,x:e.clientX,y:e.clientY,rect:r};canvas.setPointerCapture(e.pointerId)};
canvas.onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;const scale=drag.rect.size/canvas.getBoundingClientRect().width,px=clamp(drag.rect.x-(e.clientX-drag.x)*scale,0,w-drag.rect.size),py=clamp(drag.rect.y-(e.clientY-drag.y)*scale,0,h-drag.rect.size);x.value=w>drag.rect.size?String(px/(w-drag.rect.size)*100):'50';y.value=h>drag.rect.size?String(py/(h-drag.rect.size)*100):'50';render()};
canvas.onpointerup=canvas.onpointercancel=()=>{drag=null};dialog.querySelector('[data-crop=cancel]').onclick=cancel;dialog.addEventListener('cancel',e=>{e.preventDefault();cancel()});
save.onclick=async()=>{save.disabled=true;status.textContent='Подготавливаю аватар…';try{const out=document.createElement('canvas');out.width=out.height=512;const r=rectangle(w,h,Number(zoom.value),Number(x.value),Number(y.value));out.getContext('2d').drawImage(image,r.x,r.y,r.size,r.size,0,0,512,512);const blob=await new Promise(resolve=>out.toBlob(resolve,'image/webp',.85));if(closed)return;if(!blob)throw Error('Не удалось подготовить фото.');const bytes=new Uint8Array(await blob.arrayBuffer());if(closed)return;let text='';for(let i=0;i<bytes.length;i+=32768)text+=String.fromCharCode(...bytes.subarray(i,i+32768));finish(btoa(text))}catch(e){if(!closed){status.textContent=e.message||'Не удалось подготовить фото.';save.disabled=false}}};
window.addEventListener('hashchange',cancel);window.addEventListener('pagehide',cancel);try{document.body.append(dialog);if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');render();dialog.querySelector('[data-crop=zoom]').focus()}catch(e){finish(null,Error('Не удалось открыть редактор фото. Обнови страницу и попробуй ещё раз.'))}});
}finally{image?.close?.();if(url)URL.revokeObjectURL(url)}}
window.BoraAvatarCrop={open,cancel:cancelPending,rectangle};
})();
